mapper.select:
SELECT , CAST(price.attribute_value AS UNSIGNED) as price_range, CASE WHEN delivery.attribute_value = 'True' THEN true ELSE false END as has_delivery, CASE WHEN takeout.attribute_value = 'True' THEN true ELSE false END as has_take_out, CASE WHEN outdoor.attribute_value = 'True' THEN true ELSE false END as has_outdoor_seating, CASE WHEN kids.attribute_value = 'True' THEN true ELSE false END as good_for_kids, (b.stars * 0.6 + LEAST(b.review_count / 10.0, 4) * 0.4) as popularity_score FROM businesses b LEFT JOIN business_attributes price ON b.business_id = price.business_id AND price.attribute_name = 'RestaurantsPriceRange2' LEFT JOIN business_attributes delivery ON b.business_id = delivery.business_id AND delivery.attribute_name = 'RestaurantsDelivery' LEFT JOIN business_attributes takeout ON b.business_id = takeout.business_id AND takeout.attribute_name = 'RestaurantsTakeOut' LEFT JOIN business_attributes outdoor ON b.business_id = outdoor.business_id AND outdoor.attribute_name = 'OutdoorSeating' LEFT JOIN business_attributes kids ON b.business_id = kids.business_id AND kids.attribute_name = 'GoodForKids'
AND (b.name LIKE CONCAT('%', #{query.keyword}, '%') OR b.categories LIKE CONCAT('%', #{query.keyword}, '%') OR b.address LIKE CONCAT('%', #{query.keyword}, '%'))
AND b.city = #{query.city}
AND b.state = #{query.state}
AND b.categories LIKE CONCAT('%', #{query.category}, '%')
AND price.attribute_value = #{query.priceRange}
AND b.stars >= #{query.minStars}
AND b.stars <= #{query.maxStars}
AND b.review_count >= #{query.minReviewCount}
AND b.is_open = #{query.isOpen}
AND delivery.attribute_value = 'True'
AND takeout.attribute_value = 'True'
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'RestaurantsReservations' AND ba.attribute_value = 'True')
AND outdoor.attribute_value = 'True'
AND kids.attribute_value = 'True'
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'WheelchairAccessible' AND ba.attribute_value = 'True')
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'WiFi' AND ba.attribute_value LIKE '%free%')
ORDER BY b.stars ${query.sortDir}
ORDER BY b.review_count ${query.sortDir}
ORDER BY popularity_score ${query.sortDir}
ORDER BY price_range ${query.sortDir}
ORDER BY b.stars DESC
LIMIT #{query.size} OFFSET #{query.offset}

SELECT COUNT(DISTINCT b.business_id) FROM businesses b LEFT JOIN business_attributes price ON b.business_id = price.business_id AND price.attribute_name = 'RestaurantsPriceRange2' LEFT JOIN business_attributes delivery ON b.business_id = delivery.business_id AND delivery.attribute_name = 'RestaurantsDelivery' LEFT JOIN business_attributes takeout ON b.business_id = takeout.business_id AND takeout.attribute_name = 'RestaurantsTakeOut' LEFT JOIN business_attributes outdoor ON b.business_id = outdoor.business_id AND outdoor.attribute_name = 'OutdoorSeating' LEFT JOIN business_attributes kids ON b.business_id = kids.business_id AND kids.attribute_name = 'GoodForKids'
AND (b.name LIKE CONCAT('%', #{query.keyword}, '%') OR b.categories LIKE CONCAT('%', #{query.keyword}, '%') OR b.address LIKE CONCAT('%', #{query.keyword}, '%'))
AND b.city = #{query.city}
AND b.state = #{query.state}
AND b.categories LIKE CONCAT('%', #{query.category}, '%')
AND price.attribute_value = #{query.priceRange}
AND b.stars >= #{query.minStars}
AND b.stars <= #{query.maxStars}
AND b.review_count >= #{query.minReviewCount}
AND b.is_open = #{query.isOpen}
AND delivery.attribute_value = 'True'
AND takeout.attribute_value = 'True'
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'RestaurantsReservations' AND ba.attribute_value = 'True')
AND outdoor.attribute_value = 'True'
AND kids.attribute_value = 'True'
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'WheelchairAccessible' AND ba.attribute_value = 'True')
AND EXISTS (SELECT 1 FROM business_attributes ba WHERE ba.business_id = b.business_id AND ba.attribute_name = 'WiFi' AND ba.attribute_value LIKE '%free%')
